[4081] = { en = "KILL ON SIGHT: Dark Iron Dwarves", tier = 4,
  t = "DIRECT DODEN: Dark Iron Dwarves",
  d = "In opdracht van Warlord Goretooth, bevelhebber van de Kargath Expeditionary Force:$B$BAlle troepen van General Angerforge in Blackrock Depths moeten worden vernietigd.$B$BDe mannen van Angerforge zijn meedogenloze moordenaars. Zij hebben de 109e divisie van de Kargath Expeditionary Force massaal vermoord. Helden worden gewaarschuwd: wees uiterst voorzichtig als je tegenover deze bruten staat.$B$BIedereen die de eerste linie van de troepen van General Angerforge in Blackrock Depths vernietigt, krijgt een beloning.",
  o = "Ga naar Blackrock Depths en vernietig de gemene aanvallers!$B$BWarlord Goretooth wil dat je 15 Anvilrage Guardsmen, 10 Anvilrage Wardens en 5 Anvilrage Footmen doodt. Ga terug naar hem als je taak klaar is.$b",
  p = "Wat is er, $r? Zie je niet dat ik een peloton moet leiden?$B$B",
  c = "Deze eerste aanval zal Angerforge wel even van zijn stuk brengen. Ga nu verder, soldaat. Ik heb werk te doen, gevechten te plannen en vijanden te verpletteren!$B$BKijk op de borden met 'Gezocht' voor meer werk.",
  g = { {"in opdracht van", "by order of"}, {"bevelhebber", "commander"}, {"vernietigd", "destroyed (vernietigen)"}, {"meedogenloze", "ruthless (meedogenloos)"}, {"massaal", "on a large scale, en masse"}, {"uiterst", "extremely"}, {"bruten", "brutes (bruut)"}, {"linie", "line (of troops)"}, {"aanvallers", "attackers (aanvaller)"}, {"peloton", "platoon"}, {"van zijn stuk brengen", "to throw off balance, to upset"}, {"verpletteren", "to crush"} },
},

[3701] = { en = "The Smoldering Ruins of Thaurissan", tier = 4,
  t = "De smeulende ruïnes van Thaurissan",
  d = "Ga naar de smeulende ruïnes van Thaurissan in de Burning Steppes en verzamel zoveel mogelijk informatie.$B$BMen zegt dat er overal in de ruïnes geheimzinnige relikwieën liggen. Misschien kun je daar beginnen met zoeken, $N. Pas op voor de bewakers van Thaurissan: moordenaars die de ruïnes bewaken. Zij beschermen de geheimen die daar misschien nog begraven liggen.",
  o = "Ga naar de Ruins of Thaurissan in de Burning Steppes en haal informatie uit de Thaurissan Relics. Ga terug naar Royal Historian Archesonus als je de informatie hebt.",
  p = "Breng je nieuwe informatie?",
  c = "O jee! Deze informatie verklaart heel veel over Thaurissan.$B$BEr is nog veel meer te leren!",
