[4182] = { en = "Dragonkin Menace", tier = 4,
  t = "Dreiging van het drakenvolk",
  d = "Het leven in de Burning Steppes zit vol conflict.$B$BKijk nou eens naar deze plek! We weten weinig over wat er met deze gebouwen is gebeurd. Maar we weten wel dat dit allemaal ooit, voor de grote explosie, bij de Redridge-bergketen hoorde.$B$BGenoeg geklaagd! We hebben een probleem, $N. Misschien heb je het drakenvolk onder deze bergkam gezien. We hebben hulp nodig om ze terug te dringen. Dood er zoveel als je kunt en kom dan terug. Als het lukt, kunnen we misschien over andere dingen praten.$b",
  o = "Dood 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin en 1 Black Drake. Ga terug naar Helendis Riverhorn als de taak klaar is.",
  p = "Hoe gaat de drakenjacht?",
  c = "Mooi gedood, $N. Nu we weten dat je je redt tussen het drakenvolk, kunnen we over dringender zaken praten.",
  g = { {"dreiging", "threat, menace"}, {"drakenvolk", "dragonkin"}, {"bergketen", "mountain range"}, {"geklaagd", "lamented, complained (klagen)"}, {"bergkam", "ridge"}, {"terug te dringen", "to push back (terugdringen)"}, {"drakenjacht", "dragon hunt"}, {"je redt", "you manage, cope (zich redden)"}, {"dringender", "more pressing (dringend)"}, {"zaken", "matters (zaak)"} },
},

[4183] = { en = "The True Masters", tier = 4,
  t = "De echte meesters",
  d = "We dachten altijd dat de Blackrock-orks zo waren door hun wrede opvoeding. Maar wat we hier, in hun thuisland, hebben gevonden, vertelt een ander verhaal.$B$BHet is inderdaad bloeddorst en zin in strijd die hun kracht geven. Maar het is de zwarte drakenvlucht die de orks van Blackrock beheerst. We vermoeden dat de zwarte drakenvlucht hen vult met woede en vijandigheid.$B$BBreng deze brief naar Magistrate Solomon. Hij weet wat er moet gebeuren.$B$B<Helendis geeft je een verzegelde brief.>",
  o = "Reis naar Lakeshire en breng Helendis Riverhorn's Letter naar Magistrate Solomon. ",
  p = "Gegroet, $N. Hebben we elkaar al eens ontmoet? Je komt me een beetje bekend voor.",
  c = "<Magistrate Solomon opent de verzegelde brief van Helendis en begint te lezen.>",
  g = { {"orks", "orcs (ork)"}, {"wrede", "savage, cruel (wreed)"}, {"opvoeding", "upbringing"}, {"bloeddorst", "bloodlust"}, {"drakenvlucht", "dragonflight"}, {"beheerst", "controls (beheersen)"}, {"vermoeden", "suspect (vermoeden)"}, {"vijandigheid", "hostility"}, {"verzegelde", "sealed (verzegelen)"}, {"gegroet", "greetings"}, {"bekend voor", "familiar (bekend voorkomen)"} },
},

[4184] = { en = "The True Masters", tier = 4,
  t = "De echte meesters",
  d = "Dit is somber nieuws, $N. Het is ontmoedigend om te ontdekken dat onze ergste vijanden maar pionnen zijn van een veel grotere dreiging. Lakeshire kan op geen enkele manier een aanval van zowel de Blackrock-orks als de zwarte drakenvlucht overleven. Als Lakeshire valt voor deze dreiging, valt Darkshire daarna, en dan? Goldshire? Stormwind zelf?$B$BJe moet deze informatie meteen naar Highlord Bolvar Fordragon in Stormwind brengen! Als Stormwind hierdoor niet komt helpen, dan helpt niets meer en is alles verloren.$b",
  o = "Reis naar Stormwind en breng Solomon's Plea naar Highlord Bolvar Fordragon.$B$BBolvar verblijft in Stormwind Keep. ",
  p = "Wat brengt je naar Stormwind Keep?",
  c = "Draken? Onmogelijk!",
  g = { {"somber", "grim, gloomy"}, {"ontmoedigend", "disheartening"}, {"pionnen", "pawns (pion)"}, {"dreiging", "threat, menace"}, {"overleven", "to survive"}, {"drakenvlucht", "dragonflight"}, {"verloren", "lost (verliezen)"}, {"verblijft", "resides, stays (verblijven)"}, {"onmogelijk", "impossible"} },
},

[4185] = { en = "The True Masters", tier = 4,
  t = "De echte meesters",
  d = "Solomon schetst een somber beeld. Toch kunnen we het ons niet veroorloven om onze troepen, die al dun verspreid zijn, op basis van een vermoeden naar Lakeshire te sturen. Ik heb bewijs voor deze beweringen nodig voordat ik iets kan doen.$B$BPraat met Lady Prestor, $N. Ze is een geleerde vrouw en weet veel over draken en drakenvolk. Misschien kan zij wat licht op deze situatie werpen.$b",
  o = "Praat met Highlord Bolvar Fordragon nadat je met Lady Katrana Prestor hebt gepraat.",
  p = "<Bolvar kijkt je aandachtig aan.>",
  c = "<Bolvar legt zijn hand onder zijn kin, alsof hij diep nadenkt.>$B$BIk respecteer het standpunt van Lady Prestor, maar ik denk dat er een oplossing voor dit dilemma is die al onze zorgen kan wegnemen. ",
  e = "Advies van Lady Prestor",
  g = { {"schetst", "paints, sketches (schetsen)"}, {"veroorloven", "to afford"}, {"verspreid", "spread (verspreiden)"}, {"vermoeden", "speculation, suspicion"}, {"beweringen", "claims (bewering)"}, {"geleerde", "learned (geleerd)"}, {"licht op werpen", "to shed light on"}, {"aandachtig", "intently"}, {"standpunt", "stance, point of view"}, {"wegnemen", "to take away, remove"} },
},

