[4224] = { en = "The True Masters", tier = 4,
  t = "De echte meesters",
  d = "Wat? Dacht je dat je de eerste was? Hoeveel soldaten moeten we nog verliezen voordat Stormwind iets doet?$B$BWe hadden enorm veel informatie over de Blackrock-dreiging verzameld voordat we onze bevelhebber, Marshal Windsor, kwijtraakten. Met Marshal Windsor verdween ook al onze kostbare informatie.$B$BWat we nodig hebben, zijn die documenten. Praat met Ragged John, $N. Hij was bij Windsor toen ze werden aangevallen door een rooftroep van Blackrock. Hij is voor het laatst gezien in een grot in het noorden.",
  o = "Praat met Ragged John om te horen wat er met Marshal Windsor is gebeurd. Ga terug naar Marshal Maxwell als je deze taak hebt voltooid.$B$BJe herinnert je dat Marshal Maxwell zei dat je hem moest zoeken in een grot in het noorden.",
  p = "Heb je John al gesproken?",
  c = "Ik had je kunnen waarschuwen, maar waar is dan de lol?",
