[8945] = { en = "Dead Man's Plea", tier = 4,
  t = "De smeekbede van een dode",
  d = "Ik zal je de informatie geven waar je om vraagt, $N. Maar er zijn nu dringender zaken.$B$BMijn geliefde vrouw is gevangengenomen door het ondode tuig van Rivendare.$B$BIk was er sterk op tegen dat ze meedeed aan de dwaze kruistocht van de Argent Dawn, maar dat is niet meer belangrijk. Je moet afmaken wat ik heb geprobeerd. Je moet Ysida redden uit de klauwen van de Baron!",
  o = "Ga naar Stratholme en red Ysida Harmon uit de handen van Baron Rivendare.",
  p = "Zeg me, leeft Ysida nog?",
  c = "Dank je dat je me hebt gered... Ik was bang voor mijn leven. Neem dit alsjeblieft aan als een klein teken van mijn dankbaarheid.$B$BAnthion is... nee... dat kan niet...",
  o1 = "Ysida bevrijd",
  g = { {"smeekbede", "plea"}, {"dringender", "more pressing (dringend)"}, {"geliefde", "beloved"}, {"gevangengenomen", "taken prisoner (gevangennemen)"}, {"tuig", "scum"}, {"er sterk op tegen", "strongly against it"}, {"dwaze", "foolish (dwaas)"}, {"kruistocht", "crusade"}, {"klauwen", "clutches, claws (klauw)"}, {"dankbaarheid", "gratitude"}, {"bevrijd", "freed (bevrijden)"} },
},

[8946] = { en = "Proof of Life", tier = 4,
  t = "Bewijs van leven",
  d = "Het is het wreedste lot dat mijn geliefde is gestorven terwijl hij mij probeerde te redden. Toch zeg je dat je met hem kunt praten.$B$BBreng hem dit medaillon als bewijs dat het goed met me gaat. Hij mag niet in deze wereld blijven hangen; mijn hart zou dat niet kunnen verdragen.$B$BVaarwel, $N. Ik zal altijd bij je in het krijt staan.",
  o = "Breng Ysida's Locket naar Anthion Harmon in de Eastern Plaguelands.",
  p = "Ysida... leeft ze nog?",
  c = "Dat medaillon... je hebt haar gevonden! Eindelijk kan ik in vrede rusten.$B$BIk zal nu al je vragen beantwoorden, $N. Maar haast je, mijn tijd in deze wereld is kort.",
  g = { {"bewijs", "proof"}, {"wreedste", "cruellest (wreed)"}, {"lot", "fate"}, {"geliefde", "beloved"}, {"medaillon", "locket, medallion"}, {"blijven hangen", "to linger"}, {"verdragen", "to bear, endure"}, {"vaarwel", "farewell"}, {"in het krijt staan", "to be in (someone's) debt"}, {"in vrede rusten", "to rest in peace"}, {"haast je", "hurry (zich haasten)"} },
},

[8947] = { en = "Anthion's Strange Request", tier = 4,
  t = "Het vreemde verzoek van Anthion",
  d = "We begrepen niet hoe belangrijk het medaillon van Valthalak was, dus werd het verdeeld samen met de rest van de buit. Het eerste stuk werd meegenomen door een dwerg die Theldren heet. Ik probeerde het van hem terug te krijgen, maar hij sloeg me bijna dood. Je zult het stuk met geweld moeten nemen.$B$BHet laatste wat ik over hem hoorde, was dat hij gladiator was geworden voor de Dark Iron-dwergen. Het wordt wel een uitdaging om hem met jou te laten vechten.$B$BVerzamel de volgende materialen voor me. Je zult ze nodig hebben.",
  o = "Breng 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth en 4 Cured Rugged Hides naar Anthion Harmon in de Eastern Plaguelands.",
  p = "Heb je de materialen gekregen waar ik om vroeg, $N?",
  c = "Uitstekend. Ik zal ze veranderen in iets wat beter past bij wat we nodig hebben.",
  g = { {"verzoek", "request"}, {"medaillon", "medallion"}, {"verdeeld", "divided (verdelen)"}, {"buit", "spoils, loot"}, {"sloeg me bijna dood", "beat me within an inch of my life"}, {"met geweld", "by force"}, {"uitdaging", "challenge"}, {"verzamel", "gather (verzamelen)"}, {"materialen", "materials (materiaal)"}, {"uitstekend", "excellent"} },
},

[8948] = { en = "Anthion's Old Friend", tier = 4,
  t = "Een oude vriend van Anthion",
  d = "Theldren gaat niet graag een eerlijk gevecht aan. Ik heb dit vaandel zo gemaakt dat het de kleuren van zijn familie laat zien.$B$BMet wat extra tovenarij zal dit vaandel hem uitdagen op een manier die hij niet kan weerstaan.$B$BEen oude kennis van mij, Falrin, weet precies hoe dat moet. Hij heeft een bijzondere manier om... mensen te ergeren. Je vindt hem in de bibliotheek van Dire Maul.",
  o = "Breng de onvoltooide Banner of Provocation naar Falrin Treeshaper in de bibliotheek van Dire Maul.",
  p = "Zeg het maar, vreemdeling. Zie je niet dat ik het druk heb?",
  c = "Heeft Anthion je gestuurd, zeg je? Ik dacht dat hij dood was. Nou ja, ik heb in mijn leven wel vreemdere dingen gehoord.$B$BGoed dan. Wat wil je dat ik met dit vaandel doe?",
  g = { {"eerlijk", "fair"}, {"vaandel", "banner"}, {"tovenarij", "sorcery"}, {"uitdagen", "to provoke, challenge"}, {"weerstaan", "to resist"}, {"kennis", "acquaintance"}, {"ergeren", "to annoy, aggravate"}, {"onvoltooide", "incomplete (onvoltooid)"}, {"vreemdeling", "stranger"}, {"vreemdere", "stranger (vreemd)"} },
},

[8949] = { en = "Falrin's Vendetta", tier = 4,
  t = "Falrins vendetta",
  d = "Ja, het klopt dat ik deze betovering ken die je nodig hebt, $c. Maar ik geef niet zomaar gunsten weg, ook al ben je hier gestuurd door een oude vriend.$B$BIk voel alleen maar haat en minachting voor onze ruwe ogerburen. En niet alleen voor hen: ik haat de volgelingen van Omokk net zo erg als de volgelingen van King Gordok.$B$BIk wil dat je ze doodt. Dood er heel veel! Breng me de kralen die ze om hun nek dragen als bewijs van je werk. Doe dit, dan praten we over je verzoek.",
  o = "Verzamel 25 Ogre Warbeads van ogers in Dire Maul of Blackrock Spire en ga terug naar Falrin Treeshaper in het Athenaeum in Dire Maul.",
  p = "Heb je de gunst gedaan waar ik om vroeg, $N?",
  c = "Hmmm... vreemd genoeg voel ik me niet beter over de dood van mijn broer door die bruten.$B$BNou, jij hebt je deel van de afspraak gedaan. Eens kijken wat ik voor je kan doen.",
  g = { {"betovering", "enchantment"}, {"gunsten", "favours (gunst)"}, {"haat", "hatred"}, {"minachting", "contempt"}, {"ruwe", "brutish, rough (ruw)"}, {"ogerburen", "ogre neighbours (ogerbuur)"}, {"volgelingen", "followers (volgeling)"}, {"kralen", "beads (kraal)"}, {"verzoek", "request"}, {"ogers", "ogres (oger)"}, {"vreemd genoeg", "strangely enough"}, {"bruten", "brutes (bruut)"}, {"afspraak", "deal, bargain"} },
},

[8950] = { en = "The Instigator's Enchantment", tier = 4,
  t = "De betovering van de opruier",
  d = "Ik kan de betovering die je nodig hebt heel makkelijk op het vaandel leggen, $N. Helaas heb ik de materialen niet, want er wordt maar heel zelden om zo'n bezwering gevraagd.$B$BIk heb de essentie nodig van een van de Eldreth-geesten die door deze zalen spoken, een handvol duistere runen uit Scholomance en een paar grote stralende scherven. Breng me deze ingrediënten, dan doe ik dit voor je.",
  o = "Breng het volgende naar Falrin Treeshaper in Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes en 8 Large Brilliant Shards.",
  p = "Heb je de materialen verzameld die ik nodig heb, $N?",
  c = "Ja, deze zijn precies goed. Als ik klaar ben, kan geen enkele kracht ter wereld je slachtoffer tegenhouden om je uitdaging aan te nemen.",
  g = { {"opruier", "instigator"}, {"betovering", "enchantment"}, {"vaandel", "banner"}, {"zelden", "rarely"}, {"bezwering", "charm, spell"}, {"essentie", "essence"}, {"spoken", "haunt (spoken)"}, {"handvol", "handful"}, {"runen", "runes (rune)"}, {"stralende", "brilliant, shining (stralend)"}, {"scherven", "shards (scherf)"}, {"slachtoffer", "victim"}, {"tegenhouden", "to stop, hold back"}, {"uitdaging", "challenge"} },
},

[8977] = { en = "Return to Deliana", tier = 4,
  t = "Terug naar Deliana",
  d = "Het was fijn om met je samen te werken, $N. Hier is het eindproduct.$B$BIk hoop dat het je helpt bij wat je nu probeert te doen. En hé, als je het niet erg vindt, vertel het verder. Ik zou best meer klanten willen!",
  o = "Breng de Extra-Dimensional Ghost Revealer naar Deliana in Ironforge.",
  p = "Ben je terug?",
  c = "Uitstekend! Je hebt het goed gedaan, $N. Ik weet niet zeker of ik het vakwerk van de goblin vertrouw, maar ik heb geen andere keus.",
  g = { {"samen te werken", "to work together (samenwerken)"}, {"eindproduct", "finished product"}, {"als je het niet erg vindt", "if you don't mind"}, {"vertel het verder", "spread the word (verder vertellen)"}, {"klanten", "customers (klant)"}, {"vakwerk", "craftsmanship"}, {"keus", "choice"} },
},

[8996] = { en = "Return to Bodley", tier = 4,
  t = "Terug naar Bodley",
  d = "Deze keer negeer ik je brutaliteit, $c, omdat je vandaag iets edels hebt gedaan: je hebt de rest van mijn gestolen geest aan mij teruggegeven. Je bent duidelijk zwak, $r, maar toch heb je moed getoond. Degenen die van mij stalen, hadden die moed niet, en zullen die waarschijnlijk nooit hebben!$B$BGa terug naar hen, voordat ik me bedenk en je ter plekke dood. Ga terug en zeg hun dat ze veilig zijn... voorlopig.",
  o = "Ga terug naar Bodley in Blackrock Mountain en geef hem de Brazier of Beckoning.",
  p = "$N, je bent terug en je leeft nog! Nou, dan leeft in elk geval één van ons nog.$B$BJe moet me er alles over vertellen!",
  c = "Heeft hij dat echt allemaal gezegd? Wauw, ik kan niet geloven dat hij de spookachtige moordenaars en sluipers terugroept, ook al liet hij doorschemeren dat hij mijn levende metgezellen later nog meer kwaad wil doen.$B$BDit is een geweldige dag, $N! Je hebt bereikt wat maar weinigen ooit konden. En je hebt ons, in elk geval voor een deel, verlost van onze vroegere zonden.$B$BDank je! Als teken van waardering wil ik je dit geven. Hiermee kun je geesten oproepen op dezelfde spookplekken als eerder, en ook op een paar andere.",
  g = { {"brutaliteit", "impertinence, cheek"}, {"edels", "noble (thing) (edel)"}, {"ter plekke", "on the spot"}, {"voorlopig", "for now"}, {"spookachtige", "ghostly, spectral (spookachtig)"}, {"sluipers", "stalkers (sluiper)"}, {"liet doorschemeren", "hinted (laten doorschemeren)"}, {"metgezellen", "companions (metgezel)"}, {"verlost", "freed, absolved (verlossen)"}, {"zonden", "sins (zonde)"}, {"waardering", "appreciation"}, {"oproepen", "to summon"} },
},

})

